import os, sys, time, multiprocessing
import torch._dynamo  # noqa: F401  pre-import before gym/overcooked (torch 2.11 flake)
import numpy as np

import os, sys, time, multiprocessing
import torch._dynamo  # noqa: F401  pre-import before gym/overcooked (torch 2.11 flake)
from stable_baselines3 import PPO

class SwitchStartEnv(OvercookedV3Env):
    """Start with a fixed partner, but keep mid-episode switching on."""

    def __init__(self, *a, **kw):
        super().__init__(*a, **kw)
        self._force_start = None

    def reset(self, seed=None, options=None):
        if seed is not None:
            self.seed_val = seed
        self.base_env.reset()
        for a in self.pool.values():
            a.reset(); a.set_agent_index(1); a.set_mdp(self.mdp)
        if self._force_start is not None:
            self._partner_idx = PARTNER_TYPES.index(self._force_start)
        else:
            self._partner_idx = np.random.randint(len(PARTNER_TYPES))
        self._switch_timer = 0
        self._steps = 0
        return self._get_obs(), {}


class SwitchStartMemoryEnv(SwitchStartEnv):
    """Memory env + fixed START partner, switching kept on."""

    def __init__(self, memory=4, *a, **kw):
        from iigc.envs._overcooked.overcooked_memory_env import OvercookedMemoryEnv
        self._mem_cls = OvercookedMemoryEnv
        super().__init__(memory=memory, *a, **kw)
        self.memory_k = memory
        self._history = None

    def _get_obs(self):
        base = super()._get_obs()
        if self._history is None:
            self._history = [base] * self.memory_k
        self._history = self._history[1:] + [base]
        return np.concatenate(self._history).astype(np.float32)

