            "output": "<path>C:\\Users\\Flavi\\opencode\\IIGC\\src\\iigc\\metrics\\fields.py</path>\n<type>file</type>\n<content>\n1: \"\"\"Gradient fields for kappa measurement on a common basis.\n2: \n3: Every field is the gradient of a scalar objective w.r.t. the SAC actor\n4: parameters (theta), computed on the SAME rollouts. Only the objective changes,\n5: so kappa differences are attributable to the field, not to the network, data,\n6: or relations.\n7: \n8: Fields (mode-seeking -> mean-seeking):\n9:   - reinforce : return-weighted grad log pi(a_taken)    [hard mode-seeking]\n10:   - awr       : advantage-weighted grad log pi(a_taken) [intermediate]\n11:   - softq     : SAC actor loss grad                      [soft]\n12:   - expq      : expected-Q grad sum_a pi(a) Q(a)         [mean-seeking]\n13:   - gibbs(tau): pi_tau = softmax(logits/tau), grad E[Q]  (tau -> 0 mode,\n14:                 tau -> inf mean)\n15: \"\"\"\n16: import numpy as np\n17: import torch\n18: import torch.nn.functional as F\n19: \n20: FIELDS = ['reinforce', 'awr', 'softq', 'expq']\n21: \n22: \n23: def kappa_and_energy(gA, gB):\n24:     avg = (gA + gB) / 2.0\n25:     e = (torch.norm(gA) ** 2 + torch.norm(gB) ** 2) / 2.0\n26:     k = (torch.norm(avg) ** 2 / max(e, 1e-10)).item()\n27:     return k, e.item()\n28: \n29: \n30: def rollout_episodes(model, env, n_eps=30, base_seed=0):\n31:     \"\"\"Collect episodes of (obs, action, reward, next_obs, done).\"\"\"\n32:     episodes = []\n33:     for ep in range(n_eps):\n34:         obs, info = env.reset(seed=base_seed + ep)\n35:         done = False\n36:         traj = []\n37:         while not done:\n38:             obs_t = torch.FloatTensor(obs).unsqueeze(0).to(model.device)\n39:             with torch.no_grad():\n40:                 act, _ = model.actor.get_action(obs_t, deterministic=True)\n41:             action = act.item()\n42:             next_obs, reward, done, trunc, info = env.step(action)\n43:             traj.append((obs, action, reward, next_obs, done))\n44:             obs = next_obs\n45:         episodes.append(traj)\n46:     return episodes\n47: \n48: \n49: def _flatten(episodes):\n50:     return [t for traj in episodes for t in traj]\n51: \n52: \n53: def _probs_logits_q(model, obs_batch, q_fn=None):\n54:     obs = torch.FloatTensor(np.array(obs_batch)).to(model.device)\n55:     logits = model.actor(obs)\n56:     probs = F.softmax(logits, dim=-1)\n57:     log_probs = F.log_softmax(logits, dim=-1)\n58:     with torch.no_grad():\n59:         if q_fn is not None:\n60:             q = q_fn(obs)\n61:         else:\n62:             q = torch.min(model.critic1(obs), model.critic2(obs))\n63:     return obs, probs, log_probs, q\n64: \n65: \n66: def compute_grad(model, loss):\n67:     model.actor.zero_grad()\n68:     loss.backward()\n69:     gv = [p.grad.detach().clone().flatten() for p in model.actor.parameters() if p.grad is not None]\n70:     return torch.cat(gv) if gv else torch.zeros(1)\n71: \n72: \n73: def loss_reinforce(model, episodes):\n74:     total = torch.zeros(1, device=model.device); count = 0\n75:     for traj in episodes:\n76:         G = sum(t[2] for t in traj)\n77:         obs = torch.FloatTensor(np.array([t[0] for t in traj])).to(model.device)\n78:         log_probs = F.log_softmax(model.actor(obs), dim=-1)\n79:         act = torch.tensor([t[1] for t in traj]).to(model.device)\n80:         lp = log_probs[range(len(act)), act]\n81:         total = total + (-lp * G).sum()\n82:         count += len(traj)\n83:     return total / max(count, 1)\n84: \n85: \n86: def loss_awr(model, episodes, tau=1.0, q_fn=None):\n87:     trans = _flatten(episodes)\n88:     act_b = torch.tensor([t[1] for t in trans]).to(model.device)\n89:     _, probs, log_probs, q = _probs_logits_q(model, [t[0] for t in trans], q_fn)\n90:     v = (probs * q).sum(dim=-1)\n91:     adv = q[range(len(act_b)), act_b] - v\n92:     w = torch.exp(adv / tau)\n93:     lp = log_probs[range(len(act_b)), act_b]\n94:     return (-lp * w).mean()\n95: \n96: \n97: def loss_softq(model, episodes, q_fn=None):\n98:     trans = _flatten(episodes)\n99:     _, probs, log_probs, q = _probs_logits_q(model, [t[0] for t in trans], q_fn)\n100:     alpha = model.log_alpha.exp().detach()\n101:     return (probs * (alpha * log_probs - q)).sum(dim=-1).mean()\n102: \n103: \n104: def loss_expq(model, episodes, q_fn=None):\n105:     trans = _flatten(episodes)\n106:     _, probs, _, q = _probs_logits_q(model, [t[0] for t in trans], q_fn)\n107:     return -(probs * q).sum(dim=-1).mean()\n108: \n109: \n110: def loss_gibbs_expq(model, episodes, tau, q_fn=None):\n111:     trans = _flatten(episodes)\n112:     obs = torch.FloatTensor(np.array([t[0] for t in trans])).to(model.device)\n113:     logits = model.actor(obs)\n114:     pi = F.softmax(logits / tau, dim=-1)\n115:     with torch.no_grad():\n116:         if q_fn is not None:\n117:             q = q_fn(obs)\n118:         else:\n119:             q = torch.min(model.critic1(obs), model.critic2(obs))\n120:     return -(pi * q).sum(dim=-1).mean()\n121: \n122: \n123: def field_loss(model, episodes, name, q_fn=None):\n124:     if name == 'reinforce':\n125:         return loss_reinforce(model, episodes)\n126:     if name == 'awr':\n127:         return loss_awr(model, episodes, q_fn=q_fn)\n128:     if name == 'softq':\n129:         return loss_softq(model, episodes, q_fn=q_fn)\n130:     if name == 'expq':\n131:         return loss_expq(model, episodes, q_fn=q_fn)\n132:     raise ValueError(name)\n\n(End of file - total 132 lines)\n</content>",
