              "preview": "\"\"\"\nA2C on 510K with action masking.\nParallel envs + kappa from REINFORCE gradient.\n\"\"\"\nimport os, sys, json, time, multiprocessing\nimport numpy as np, torch\n\nfrom iigc.envs._510k.dqn_wrapper import FiveTenKMaskedEnv, MASK_DIM, MAX_ACTIONS\nfrom stable_baselines3 import A2C\nfrom stable_baselines3.common.vec_env import SubprocVecEnv, VecMonitor\nfrom stable_baselines3.common.callbacks import CheckpointCallback\n\nROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..', '..'))\nMODEL_DIR = os.path.join(ROOT, 'data', 'models', '510k_a2c')\nKAPPA_DIR = os.path.join(ROOT, 'data', 'kappa', '510k_a2c')\nLOG_DIR = os.path.join(ROOT, 'data', 'logs', '510k_a2c')\nos.makedirs(MODEL_DIR, exist_ok=True)\nos.makedirs(KAPPA_DIR, exist_ok=True)\nos.makedirs(LOG_DIR, exist_ok=True)\n",
