ss_expq(model, episodes)\n145:     raise ValueError(name)\n146: \n147: \n148: def run():\n149:     results = {}\n150:     for mode in MODES:\n151:         results[mode] = {}\n152:         for seed in SEEDS:\n153:             fp = os.path.join(MODEL_DIR, f'510k_sac_{mode}_seed{seed}.pt')\n154:             if not os.path.exists(fp):\n155:                 continue\n156:             sac = DiscreteSAC(112 + MASK_DIM, MASK_DIM, MAX_ACTIONS, device='cpu')\n157:             sac.load(fp)\n158:             sac.actor.eval()\n159: \n160:             env_a = FiveTenKMaskedEnv(mode=mode)\n161:             eps_a = rollout_episodes(sac, env_a, base_seed=SEED_A); env_a.close()\n162:             env_b = FiveTenKMaskedEnv(mode=mode)\n163:             eps_b = rollout_episodes(sac, env_b, base_seed=SEED_B); env_b.close()\n164: \n165:             ra = np.mean([sum(t[2] for t in traj) for traj in eps_a])\n166:             rb = np.mean([sum(t[2] for t in traj) for traj in eps_b])\n167: \n168:             row = {'rA': ra, 'rB': rb, 'fields': {}, 'gibbs': {}}\n169:             for name in FIELDS:\n170:                 gA = compute_grad(sac, field_loss(sac, eps_a, name))\n171:                 gB = compute_grad(sac, field_loss(sac, eps_b, name))\n172:                 k, e = kappa_and_energy(gA, gB)\n173:                 row['fields'][name] = {'kappa': k, 'energy': e}\n174:                 print(f'{mode} s{seed} {name:10}: κ={k:.4f} (E={e:.1e})')\n175: \n176:             for tau in TAUS:\n177:                 gA = compute_grad(sac, loss_gibbs_expq(sac, eps_a, tau))\n178:                 gB = compute_grad(sac, loss_gibbs_expq(sac, eps_b, tau))\n179:                 k, e = kappa_and_energy(gA, gB)\n180:                 row['gibbs'][str(tau)] = {'kappa': k, 'energy': e}\n181:                 print(f'{mode} s{seed} gibbs τ={tau:<4}: κ={k:.4f} (E={e:.1e})')\n182: \n183:             results[mode][f'seed{seed}'] = row\n184:             print()\n185: \n186:     print(f'\\n{\"=\"*70}\\nSUMMARY  (mean over seeds)')\n187:     for mode in MODES:\n188:         print(f'\\n--- {mode} ---')\n189:         for name in FIELDS:\n190:             vals = [results[mode][s]['fields'][name]['kappa'] for s in results[mode]]\n191:             if vals:\n192:                 print(f'  {name:10}: κ={np.mean(vals):.4f} ± {np.std(vals):.4f}')\n193:         print('  gibbs τ sweep:')\n194:         for tau in TAUS:\n195:             vals = [results[mode][s]['gibbs'][str(tau)]['kappa'] for s in results[mode]]\n196:             if vals:\n197:                 print(f'    τ={tau:<4}: κ={np.mean(vals):.4f} ± {np.std(vals):.4f}')\n198: \n199:     with open(os.path.join(OUT_DIR, 'results.json'), 'w') as f:\n200:         json.dump(results, f, indent=2, default=float)\n201:     print(f'\\nSaved: {os.path.join(OUT_DIR, \"results.json\")}')\n202: \n203: \n204: if __name__ == '__main__':\n205:     run()\n\n(End of file - total 205 lines)\n</content>",
